# Each dataset above that uses a Library creates a new node for it.
# Merge all these to a single node for each library
# This also applies to other nodes such as CTCatalogue
MERGE_UNWANTED_DUPLICATES = """
MATCH (l:Library)
WITH collect(l) as nodes, l.name as names
CALL apoc.refactor.mergeNodes(nodes, {properties:"overwrite", mergeRels:true})
YIELD node
RETURN node;

MATCH (c:CTCatalogue)
WITH collect(c) as nodes, c.name as names
CALL apoc.refactor.mergeNodes(nodes, {properties:"overwrite", mergeRels:true})
YIELD node
RETURN node;

MATCH (term:CTTermRoot)--(context:CTTermContext)--(codelist:CTCodelistRoot)
WITH term,codelist, COLLECT(context) AS nodes
CALL apoc.refactor.mergeNodes(nodes, {properties:"overwrite", mergeRels:true})
YIELD node
RETURN node;

MATCH (udr:UnitDefinitionRoot)-[:LATEST]-(udv:UnitDefinitionValue)
WITH udr, COLLECT(udv) AS nodes
CALL apoc.refactor.mergeNodes(nodes, {properties:"overwrite", mergeRels:true})
YIELD node
RETURN node;

MATCH (nr:NumericValueRoot)-[:LATEST]-(nv:NumericValue)
WITH nr, COLLECT(nv) AS nodes
CALL apoc.refactor.mergeNodes(nodes, {properties:"overwrite", mergeRels:true})
YIELD node
RETURN node;
"""

